using pii = pair<int,int>;

struct FenwickTree {
    int n;
    vector<int> bit;
    FenwickTree(int _n): n(_n), bit(n+1, 0) {}
    void update(int i, int delta) {
        for (; i <= n; i += i & -i)
            bit[i] += delta;
    }
    int query(int i) const {
        int s = 0;
        for (; i > 0; i -= i & -i)
            s += bit[i];
        return s;
    }
    int find_kth(int k) const {
        int pos = 0;
        int bit_mask = 1 << (31 - __builtin_clz(n));
        for (; bit_mask; bit_mask >>= 1) {
            int nxt = pos + bit_mask;
            if (nxt <= n && bit[nxt] < k) {
                pos = nxt;
                k -= bit[nxt];
            }
        }
        return pos + 1;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    int m = 2*n + 1;
    vector<int> a(m);
    for (int i = 0; i < m; i++) {
        cin >> a[i];
    }
    vector<pair<int,int>> queries(q);
    
    vector<int> all;
    all.reserve(m + q);
    for (int x : a) all.push_back(x);
    for (int i = 0; i < q; i++) {
        cin >> queries[i].first >> queries[i].second;
        queries[i].first;
        all.push_back(queries[i].second);
    }
    sort(all.begin(), all.end());
    all.erase(unique(all.begin(), all.end()), all.end());

    for (int i = 0; i < m; i++) {
        a[i] = int(lower_bound(all.begin(), all.end(), a[i]) - all.begin()) + 1;
    }
    for (int i = 0; i < q; i++) {
        queries[i].second = int(lower_bound(all.begin(), all.end(), queries[i].second) - all.begin()) + 1;
    }
    
    FenwickTree fw(all.size());
    for (int x : a) fw.update(x, 1);
    
    int half = (m + 1) / 2;
    debug(a);
    for (int i = 0; i < q; i++) {
        int idx = queries[i].first;
        int newv = queries[i].second;
        debug(idx);
        fw.update(a[idx], -1);
        a[idx] = newv;
        fw.update(a[idx], 1);
        int mid_idx = fw.find_kth(half);
        cout << all[mid_idx - 1] << '\n';
    }
}
